package com.pxr.cymatic.ui.components
import android.annotation.SuppressLint import androidx.compose.foundation.clickable import androidx.compose.foundation.layout.Arrangement import androidx.compose.foundation.layout.Column import androidx.compose.foundation.layout.Row import androidx.compose.foundation.layout.fillMaxWidth import androidx.compose.foundation.layout.padding import androidx.compose.foundation.lazy.LazyColumn import androidx.compose.material3.Text import androidx.compose.runtime.Composable import androidx.compose.ui.Alignment import androidx.compose.ui.Modifier import androidx.compose.ui.graphics.Color import androidx.compose.ui.text.font.Font import androidx.compose.ui.text.font.FontFamily import androidx.compose.ui.text.style.TextOverflow import androidx.compose.ui.unit.dp import androidx.compose.ui.unit.sp import com.pxr.cymatic.R import com.pxr.cymatic.data.model.AudioFile
@Composable fun AudioFileList( audioFiles: List<AudioFile>, onItemClick: (AudioFile) -> Unit, modifier: Modifier = Modifier ) { LazyColumn(modifier = modifier) { items(audioFiles.size) { i -> AudioFileItem( audioFile = audioFiles[i], onClick = { onItemClick(audioFiles[i]) } ) } } }
@Composable fun AudioFileItem( audioFile: AudioFile, onClick: () -> Unit, modifier: Modifier = Modifier ) { val metadata = audioFile.metadata val fontFamily = FontFamily(Font(R.font.lana_pixel))
@SuppressLint("DefaultLocale") fun parseDuration(durationMs: Long?): String { if (durationMs == null) return "0:00" val totalSeconds = durationMs / 1000 val minutes = totalSeconds / 60 val seconds = totalSeconds % 60 return String.format("%d:%02d", minutes, seconds) }
Row( modifier = modifier .fillMaxWidth() .clickable(onClick = onClick) .padding(24.dp, 12.dp), verticalAlignment = Alignment.Bottom, horizontalArrangement = Arrangement.SpaceBetween, ) { Column(modifier = Modifier.weight(1f)) { Text( text = metadata.title ?: "Unknown Title", color = Color(0x80D1D1D1), overflow = TextOverflow.Ellipsis, maxLines = 1, fontSize = 24.sp, fontFamily = fontFamily, ) Text( text = metadata.artist ?: "Unknown Artist", color = Color(0x80D1D1D1), overflow = TextOverflow.Ellipsis, maxLines = 1, fontSize = 20.sp, fontFamily = fontFamily, ) }
Text( text = parseDuration(metadata.duration), color = Color(0x80D1D1D1), softWrap = false, fontSize = 20.sp, fontFamily = fontFamily, ) } }

package com.pxr.cymatic.ui.components
import android.annotation.SuppressLint import androidx.compose.foundation.clickable import androidx.compose.foundation.layout.Arrangement import androidx.compose.foundation.layout.Column import androidx.compose.foundation.layout.Row import androidx.compose.foundation.layout.fillMaxWidth import androidx.compose.foundation.layout.padding import androidx.compose.foundation.lazy.LazyColumn import androidx.compose.material3.Text import androidx.compose.runtime.Composable import androidx.compose.ui.Alignment import androidx.compose.ui.Modifier import androidx.compose.ui.graphics.Color import androidx.compose.ui.text.font.Font import androidx.compose.ui.text.font.FontFamily import androidx.compose.ui.text.style.TextOverflow import androidx.compose.ui.unit.dp import androidx.compose.ui.unit.sp import com.pxr.cymatic.R import com.pxr.cymatic.data.model.AudioFile
@Composable fun AudioFileList( audioFiles: List<AudioFile>, onItemClick: (AudioFile) -> Unit, currentPlayingId: String?, modifier: Modifier = Modifier ) { LazyColumn(modifier = modifier) { items(audioFiles.size) { i -> val audioFile = audioFiles[i] AudioFileItem( audioFile = audioFile, isPlaying = currentPlayingId == audioFile.id.toString(), onClick = { onItemClick(audioFile) } ) } } }
@Composable fun AudioFileItem( audioFile: AudioFile, isPlaying: Boolean, onClick: () -> Unit, modifier: Modifier = Modifier ) { val metadata = audioFile.metadata val fontFamily = FontFamily(Font(R.font.lana_pixel)) val textColor = if (isPlaying) Color(0xFFD1D1D1) else Color(0x80D1D1D1)
@SuppressLint("DefaultLocale") fun parseDuration(durationMs: Long?): String { if (durationMs == null) return "0:00" val totalSeconds = durationMs / 1000 val minutes = totalSeconds / 60 val seconds = totalSeconds % 60 return String.format("%d:%02d", minutes, seconds) }
Row( modifier = modifier .fillMaxWidth() .clickable(onClick = onClick) .padding(24.dp, 12.dp), verticalAlignment = Alignment.Bottom, horizontalArrangement = Arrangement.SpaceBetween, ) { Column(modifier = Modifier.weight(1f)) { Text( text = metadata.title ?: "Unknown Title", color = textColor, overflow = TextOverflow.Ellipsis, maxLines = 1, fontSize = 24.sp, fontFamily = fontFamily, ) Text( text = metadata.artist ?: "Unknown Artist", color = textColor, overflow = TextOverflow.Ellipsis, maxLines = 1, fontSize = 20.sp, fontFamily = fontFamily, ) }
Text( text = parseDuration(metadata.duration), color = textColor, softWrap = false, fontSize = 20.sp, fontFamily = fontFamily, ) } }

package com.pxr.cymatic

import android.Manifest
import android.content.ComponentName
import android.os.Build
import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.material3.Surface
import androidx.compose.runtime.DisposableEffect
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.platform.LocalContext
import androidx.core.app.ActivityCompat
import androidx.media3.session.MediaController
import androidx.media3.session.SessionToken
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import com.google.common.util.concurrent.MoreExecutors
import com.pxr.cymatic.data.media.loadAudioFiles
import com.pxr.cymatic.playback.handleItemClick
import com.pxr.cymatic.ui.screen.AlbumsScreen
import com.pxr.cymatic.ui.screen.AllSongsScreen
import com.pxr.cymatic.ui.screen.ArtistsScreen
import com.pxr.cymatic.ui.screen.HomeScreen
import com.pxr.cymatic.ui.screen.SettingsScreen
import com.pxr.cymatic.ui.theme.CymaticTheme

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            ActivityCompat.requestPermissions(
                this,
                arrayOf(Manifest.permission.READ_MEDIA_AUDIO),
                1000
            )
        } else {
            ActivityCompat.requestPermissions(
                this,
                arrayOf(Manifest.permission.READ_EXTERNAL_STORAGE),
                1000
            )
        }

        val audioFiles = loadAudioFiles(this)
        val sessionToken = SessionToken(this, ComponentName(this, PlaybackService::class.java))

        setContent {
            CymaticTheme {
                val context = LocalContext.current
                var mediaController by remember { mutableStateOf<MediaController?>(null) }
                val navController = rememberNavController()

                DisposableEffect(sessionToken) {
                    val controllerFuture =
                        MediaController.Builder(context, sessionToken).buildAsync()
                    controllerFuture.addListener({
                        mediaController = controllerFuture.get()
                    }, MoreExecutors.directExecutor())

                    onDispose {
                        MediaController.releaseFuture(controllerFuture)
                    }
                }

                Surface(
                    modifier = Modifier.fillMaxSize(),
                    color = Color(0xFF000000)
                ) {
                    NavHost(navController = navController, startDestination = "home") {
                        composable("home") {
                            HomeScreen(
                                onAllSongsClick = { navController.navigate("all_songs") },
                                onArtistsClick = { navController.navigate("artists") },
                                onAlbumsClick = { navController.navigate("albums") },
                                onSettingsClick = { navController.navigate("settings") }
                            )
                        }
                        composable("all_songs") {
                            AllSongsScreen(
                                audioFiles = audioFiles,
                                onItemClick = { audioFile ->
                                    mediaController?.let { handleItemClick(audioFile, it) }
                                },
                                onBackClick = { navController.popBackStack() }
                            )
                        }
                        composable("artists") { ArtistsScreen() }
                        composable("albums") { AlbumsScreen() }
                        composable("settings") { SettingsScreen() }
                    }
                }
            }
        }
    }
}

package com.pxr.cymatic

import android.Manifest
import android.content.ComponentName
import android.os.Build
import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.material3.Surface
import androidx.compose.runtime.DisposableEffect
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.platform.LocalContext
import androidx.core.app.ActivityCompat
import androidx.media3.session.MediaController
import androidx.media3.session.SessionToken
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import com.google.common.util.concurrent.MoreExecutors
import com.pxr.cymatic.data.media.loadAudioFiles
import com.pxr.cymatic.playback.handleItemClick
import com.pxr.cymatic.ui.screen.AlbumsScreen
import com.pxr.cymatic.ui.screen.AllSongsScreen
import com.pxr.cymatic.ui.screen.ArtistsScreen
import com.pxr.cymatic.ui.screen.HomeScreen
import com.pxr.cymatic.ui.screen.SettingsScreen
import com.pxr.cymatic.ui.theme.CymaticTheme

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            ActivityCompat.requestPermissions(
                this,
                arrayOf(Manifest.permission.READ_MEDIA_AUDIO),
                1000
            )
        } else {
            ActivityCompat.requestPermissions(
                this,
                arrayOf(Manifest.permission.READ_EXTERNAL_STORAGE),
                1000
            )
        }

        val audioFiles = loadAudioFiles(this)
        val sessionToken = SessionToken(this, ComponentName(this, PlaybackService::class.java))

        setContent {
            CymaticTheme {
                val context = LocalContext.current
                var mediaController by remember { mutableStateOf<MediaController?>(null) }
                val navController = rememberNavController()

                DisposableEffect(sessionToken) {
                    val controllerFuture =
                        MediaController.Builder(context, sessionToken).buildAsync()
                    controllerFuture.addListener({
                        mediaController = controllerFuture.get()
                    }, MoreExecutors.directExecutor())

                    onDispose {
                        MediaController.releaseFuture(controllerFuture)
                    }
                }

                Surface(
                    modifier = Modifier.fillMaxSize(),
                    color = Color(0xFF000000)
                ) {
                    NavHost(navController = navController, startDestination = "home") {
                        composable("home") {
                            HomeScreen(
                                onAllSongsClick = { navController.navigate("all_songs") },
                                onArtistsClick = { navController.navigate("artists") },
                                onAlbumsClick = { navController.navigate("albums") },
                                onSettingsClick = { navController.navigate("settings") }
                            )
                        }
                        composable("all_songs") {
                            AllSongsScreen(
                                audioFiles = audioFiles,
                                onItemClick = { audioFile ->
                                    mediaController?.let { handleItemClick(audioFile, it) }
                                },
                                onBackClick = { navController.popBackStack() },
                                currentPlayingId = mediaController?.currentMediaItem?.mediaId
                            )
                        }
                        composable("artists") {
                            ArtistsScreen(onBackClick = { navController.popBackStack() })
                        }
                        composable("albums") {
                            AlbumsScreen(onBackClick = { navController.popBackStack() })
                        }
                        composable("settings") {
                            SettingsScreen(onBackClick = { navController.popBackStack() })
                        }
                    }
                }
            }
        }
    }
}

package com.pxr.cymatic.data.media
import android.annotation.SuppressLint import android.content.ContentUris import android.content.Context import android.database.Cursor import android.net.Uri import android.provider.MediaStore import androidx.core.net.toUri import com.pxr.cymatic.data.media.AudioStoreDatabase.AudioDbRecord import com.pxr.cymatic.data.media.AudioStoreDatabase.AudioIndexEntry import com.pxr.cymatic.data.model.AudioFile
fun loadCachedAudioFiles(context: Context): List<AudioFile> { return AudioStoreDatabase.getInstance(context).getAllAudio() }
fun syncAudioFilesToDb(context: Context): List<AudioFile> { val database = AudioStoreDatabase.getInstance(context) val mediaIndex = queryMediaStoreIndex(context) val dbIndex = database.getAudioIndex()
val toDelete = dbIndex.keys - mediaIndex.keys database.deleteByIds(toDelete)
val toUpsert = mediaIndex.filter { (id, mediaEntry) -> val dbEntry = dbIndex[id] dbEntry == null || dbEntry.dateModified != mediaEntry.dateModified || dbEntry.size != mediaEntry.size }.keys
if (toUpsert.isNotEmpty()) { val records = queryMediaStoreDetails(context, toUpsert.toList()) database.upsertAudio(records) }
return database.getAllAudio() }
private fun queryMediaStoreIndex(context: Context): Map<Long, AudioIndexEntry> { val results = mutableMapOf<Long, AudioIndexEntry>() val collection = MediaStore.Audio.Media.getContentUri(MediaStore.VOLUME_EXTERNAL) val projection = arrayOf( MediaStore.Audio.Media._ID, MediaStore.Audio.Media.DATE_MODIFIED, MediaStore.Audio.Media.SIZE )
context.contentResolver.query( collection, projection, null, null, null )?.use { cursor -> val idColumn = cursor.getColumnIndexOrThrow(MediaStore.Audio.Media._ID) val dateModifiedColumn = cursor.getColumnIndexOrThrow(MediaStore.Audio.Media.DATE_MODIFIED) val sizeColumn = cursor.getColumnIndexOrThrow(MediaStore.Audio.Media.SIZE)
while (cursor.moveToNext()) { val id = cursor.getLong(idColumn) val dateModified = cursor.getLong(dateModifiedColumn) val size = cursor.getInt(sizeColumn) results[id] = AudioIndexEntry(id, dateModified, size) } }
return results }
private fun queryMediaStoreDetails(context: Context, ids: List<Long>): List<AudioDbRecord> { val records = mutableListOf<AudioDbRecord>() val collection = MediaStore.Audio.Media.getContentUri(MediaStore.VOLUME_EXTERNAL) val projection = arrayOf( MediaStore.Audio.Media._ID, MediaStore.Audio.Media.SIZE, MediaStore.Audio.Media.TITLE, MediaStore.Audio.Media.ARTIST, MediaStore.Audio.Media.ALBUM, MediaStore.Audio.Media.DURATION, MediaStore.Audio.Media.BITRATE, MediaStore.Audio.Media.SAMPLERATE, MediaStore.Audio.Media.MIME_TYPE, MediaStore.Audio.Media.ALBUM_ID, MediaStore.Audio.Media.DATE_MODIFIED )
for (chunk in ids.chunked(800)) { val (selection, args) = buildIdSelection(chunk) context.contentResolver.query( collection, projection, selection, args, null )?.use { cursor -> records += cursor.toAudioRecords() } }
return records }
private fun Cursor.toAudioRecords(): List<AudioDbRecord> { val records = mutableListOf<AudioDbRecord>() val idColumn = getColumnIndexOrThrow(MediaStore.Audio.Media._ID) val titleColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.TITLE) val artistColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.ARTIST) val albumColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.ALBUM) val durationColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.DURATION) val bitRateColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.BITRATE) val sampleRateColumn = getColumnIndex(MediaStore.Audio.Media.SAMPLERATE) val formatColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.MIME_TYPE) val sizeColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.SIZE) val albumIdColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.ALBUM_ID) val dateModifiedColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.DATE_MODIFIED)
while (moveToNext()) { val id = getLong(idColumn) val title = getString(titleColumn) val artist = getString(artistColumn) val album = getString(albumColumn) val duration = if (isNull(durationColumn)) null else getLong(durationColumn) val bitRate = if (isNull(bitRateColumn)) null else getLong(bitRateColumn) val sampleRate = if (sampleRateColumn >= 0 && !isNull(sampleRateColumn)) { getLong(sampleRateColumn) } else { null } val format = getString(formatColumn) val size = getInt(sizeColumn) val albumId = getLong(albumIdColumn) val dateModified = getLong(dateModifiedColumn)
val contentUri: Uri = ContentUris.withAppendedId( MediaStore.Audio.Media.EXTERNAL_CONTENT_URI, id )
val artworkUri = ContentUris.withAppendedId( "content://media/external/audio/albumart".toUri(), albumId )
records += AudioDbRecord( id = id, uri = contentUri.toString(), size = size, title = title, artist = artist, album = album, duration = duration, bitRate = bitRate, sampleRate = sampleRate, format = format, artworkUri = artworkUri.toString(), dateModified = dateModified ) }
return records }

