for (chunk in ids.chunked(800)) { val (selection, args) = buildIdSelection(chunk) context.contentResolver.query( collection, projection, selection, args, null )?.use { cursor -> records += cursor.toAudioRecords() } }
return records }
private fun Cursor.toAudioRecords(): List<AudioDbRecord> { val records = mutableListOf<AudioDbRecord>() val idColumn = getColumnIndexOrThrow(MediaStore.Audio.Media._ID) val titleColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.TITLE) val artistColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.ARTIST) val albumColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.ALBUM) val durationColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.DURATION) val bitRateColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.BITRATE) val sampleRateColumn = getColumnIndex(MediaStore.Audio.Media.SAMPLERATE) val formatColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.MIME_TYPE) val sizeColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.SIZE) val albumIdColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.ALBUM_ID) val dateModifiedColumn = getColumnIndexOrThrow(MediaStore.Audio.Media.DATE_MODIFIED)
while (moveToNext()) { val id = getLong(idColumn) val title = getString(titleColumn) val artist = getString(artistColumn) val album = getString(albumColumn) val duration = if (isNull(durationColumn)) null else getLong(durationColumn) val bitRate = if (isNull(bitRateColumn)) null else getLong(bitRateColumn) val sampleRate = if (sampleRateColumn >= 0 && !isNull(sampleRateColumn)) { getLong(sampleRateColumn) } else { null } val format = getString(formatColumn) val size = getInt(sizeColumn) val albumId = getLong(albumIdColumn) val dateModified = getLong(dateModifiedColumn)
val contentUri: Uri = ContentUris.withAppendedId( MediaStore.Audio.Media.EXTERNAL_CONTENT_URI, id )
val artworkUri = ContentUris.withAppendedId( "content://media/external/audio/albumart".toUri(), albumId )
records += AudioDbRecord( id = id, uri = contentUri.toString(), size = size, title = title, artist = artist, album = album, duration = duration, bitRate = bitRate, sampleRate = sampleRate, format = format, artworkUri = artworkUri.toString(), dateModified = dateModified ) }
return records }
private fun buildIdSelection(ids: List<Long>): Pair<String, Array<String>> { val placeholders = ids.joinToString(",") { "?" } val selection = "${MediaStore.Audio.Media._ID} IN ($placeholders)" val args = ids.map { it.toString() }.toTypedArray() return selection to args }

